import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';

export async function runMotionBatchImagesSmoke(page,templates){
 const previous=await page.evaluate(()=>({project:JSON.stringify(project),curPage,curSec,curEl,curPane,selection,secFocus,mode:NAGWEB_STORY_EDITOR.canvasMode(),timeline:NAGWEB_STORY_TIMELINE_UI.state()})),dir=await fs.mkdtemp(path.join(os.tmpdir(),'nagweb-batch-images-'));
 const files=[];for(let i=0;i<29;i++){const file=path.join(dir,'Imagen-'+String(i+1).padStart(2,'0')+'.svg');await fs.writeFile(file,'<svg xmlns="http://www.w3.org/2000/svg" width="'+(300+i)+'" height="200"><rect width="100%" height="100%" fill="'+(i%2?'#b8dcea':'#ffad85')+'"/><text x="20" y="120" font-size="80">'+(i+1)+'</text></svg>');files.push(file);}const broken=path.join(dir,'Rota.svg');await fs.writeFile(broken,'Esto no es un SVG válido');
 async function ready(count){await page.waitForFunction(count=>{const d=document.querySelector('.nw-motion-dialog iframe')?.contentDocument;return d?.querySelectorAll('[data-nw-stream-slot]').length===count&&d.defaultView.__NAG_SCROLL_DIRECTOR?.[d.querySelector('.sc')?.dataset.id]&&d.querySelector('[data-motion-canvas]')&&Array.from(d.querySelectorAll('[data-nw-stream-slot] img')).every(n=>n.complete&&n.naturalWidth>0);},{timeout:15000},count);}
 async function slots(){return page.$eval('.nw-motion-dialog iframe',f=>Array.from(f.contentDocument.querySelectorAll('[data-nw-stream-slot]'),n=>({id:n.dataset.id,src:n.querySelector('img').getAttribute('src'),width:n.querySelector('img').naturalWidth})));}
 async function previews(){const cards=await slots();await page.waitForFunction(cards=>cards.every(c=>{const n=document.querySelector('[data-motion-layer="'+c.id+'"] img');return n?.complete&&n.naturalWidth>0&&n.getAttribute('src')===c.src;}),{},cards);const visible=await page.$$eval('[data-motion-image-preview]',ns=>ns.filter(n=>n.getClientRects().length).map(n=>({index:+n.dataset.motionImagePreview,src:n.querySelector('img').getAttribute('src'),name:n.querySelector('[data-motion-image-name]').textContent})));for(const n of visible){const expected=await page.$eval('[data-motion-content="'+n.index+'"]',n=>n.selectedOptions[0].textContent);assert.equal(n.name,expected);assert.equal(n.src,await page.$eval('.nw-motion-dialog iframe',(f,index)=>f.contentDocument.querySelectorAll('[data-nw-stream-slot] img')[index].getAttribute('src'),n.index));}}
 async function upload(...paths){await (await page.$('[data-motion-stream-batch-upload]')).uploadFile(...paths);}
 async function completed(count){await page.waitForFunction(()=>/Se cargaron/.test(document.querySelector('[data-motion-stream-batch-status]')?.textContent||''));await ready(count);}
 async function invalid(){await page.waitForFunction(()=>/No se cambió ninguna/.test(document.querySelector('[data-motion-stream-batch-status]')?.textContent||''));assert.equal(await page.$eval('[data-motion-insert-group]',n=>n.disabled),false);}
 try{
  for(const template of templates||['showcase-stream','iso-orbit','pop-grid','center-stage','orbit-bloom','ticker-tilt','ticker-loop','carousel-flow','stack-slide','iso-focus-sequence','card-toss']){
   const count=template==='focus-slider'?8:template==='focus-orbit'?20:template==='spotlight-zoom'?4:template==='column-drift'?12:template==='orbit-carousel'?4:template==='flip-grid'?8:template==='hero-reel'?7:template==='mosaic-wipe'?4:template==='stripe-reveal'||template==='diagonal-wipe'?3:template==='split-reveal'?4:template==='cascade-deck'?8:template==='position-dance'?6:template==='cover-ring'||template==='cover-ring-vertical'?8:template==='cover-flow'||template==='cover-flow-vertical'?5:template==='wheel-spin-bottom'||template==='wheel-spin'?8:template==='wheel-carousel'?6:template==='photo-orbit'?8:template==='poster-burst'||template==='deck-peel'?4:template==='film-strip'||template==='card-totem'?6:template==='iso-orbit'?9:template==='pop-grid'?6:template==='center-stage'?3:template==='carousel-flow'?5:template==='stack-slide'?4:template==='iso-focus-sequence'?10:template==='card-toss'?8:template==='cascade-drop'?4:template==='focus-shift'?4:template==='grid-reveal'?4:template==='zoom-parallax'?3:12;
   await page.evaluate(()=>{project.pages[0].sections=[mkSection({layout:'free',sdEnabled:false,elements:[mkEl('label',{text:'Exterior',name:'Exterior'})]})];curPage=0;curSec=0;curEl=0;selection=[];secFocus=false;saveProject();renderPane();renderPreview();history=[];future=[];});const before=await page.evaluate(()=>({project:JSON.stringify(project),stored:localStorage.getItem(STORE_KEY),outside:sec().elements[0]}));
   await page.evaluate(()=>NAGWEB_MOTION_LAB.open());await page.click('[data-motion-template="'+template+'"]');await ready(count);await page.click('[data-motion-library-tab="elements"]');const original=await slots();await page.click('[data-motion-layer="'+original[0].id+'"]');await page.$eval('[data-motion-stream-order]',(n,count)=>{n.value=count;n.dispatchEvent(new Event('change',{bubbles:true}));},count);await ready(count);const ordered=await slots();assert.equal(ordered.at(-1).id,original[0].id);await previews();
   await page.click('[data-motion-add-text]');await ready(count);const free=await page.$eval('.nw-motion-dialog iframe',f=>({id:f.contentDocument.querySelector('[data-motion-text]').dataset.id,text:f.contentDocument.querySelector('[data-motion-text]').textContent}));
   // The batch follows the current position order and preserves the other slots and free text.
   await upload(...files.slice(0,2));await completed(count);const first=await slots();await previews();assert.deepEqual(first.map(n=>n.id),ordered.map(n=>n.id));assert.deepEqual(first.slice(2),ordered.slice(2));assert.equal(first[0].width,300);assert.equal(first[1].width,301);assert.notEqual(first[0].src,ordered[0].src);assert.equal(await page.$eval('[data-motion-stream-batch-upload]',n=>n.value),'');assert.equal(await page.$eval('.nw-motion-dialog iframe',(f,id)=>f.contentDocument.querySelector('[data-id="'+id+'"]').textContent,free.id),free.text);
   assert.equal(await page.evaluate(()=>JSON.stringify(project)),before.project);assert.equal(await page.evaluate(()=>localStorage.getItem(STORE_KEY)),before.stored);assert.equal(await page.evaluate(()=>history.length),0);
   // Decode failure after a valid file is atomic: no partial replacements or leaked resources.
   await upload(files[2],broken);await invalid();assert.deepEqual(await slots(),first);await upload(...files.slice(0,count+1));await invalid();assert.deepEqual(await slots(),first);
   await page.click('[data-motion-library-tab="library"]');await page.click('[data-motion-insert-group]');const inserted=await page.evaluate(()=>{const g=sec().elements.find(e=>e.nwMotionInstance);return{gid:g.id,project:JSON.stringify(project),assets:project.assets.images,members:sec().elements.filter(e=>e.parent===g.id),outside:sec().elements[0]};});assert.deepEqual(inserted.outside,before.outside);const memberSlots=inserted.members.filter(e=>e.nwStreamSlot);assert.deepEqual(memberSlots.map(e=>e.id),first.map(n=>n.id));assert.equal(inserted.members.find(e=>e.id===free.id).text,free.text);assert.equal(inserted.assets.some(a=>a.name==='Rota.svg'),false);assert.equal(inserted.assets.some(a=>a.name==='Imagen-03.svg'),false,'A failed batch commits no valid partial file either');for(let i=0;i<2;i++)assert.equal(inserted.assets.find(a=>a.id===memberSlots[i].assetId).data,first[i].src);
   await page.evaluate(id=>NAGWEB_MOTION_LAB.edit(id),inserted.gid);await ready(count);assert.deepEqual(await slots(),first);await previews();await upload(files[3]);await completed(count);const changed=await slots();await previews();assert.equal(changed[0].width,303);assert.deepEqual(changed.slice(1),first.slice(1));await page.click('[data-motion-save]');const saved=await page.evaluate(()=>JSON.stringify(project));assert.notEqual(saved,inserted.project);await page.evaluate(()=>undo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),inserted.project);await page.evaluate(()=>redo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),saved);
   await page.evaluate(()=>{const f=document.createElement('iframe');f.id='batch-export';f.srcdoc=generateSite(flattenPage(page()),false,false,false);document.body.appendChild(f);});await page.waitForFunction(count=>document.querySelector('#batch-export')?.contentDocument?.querySelectorAll('[data-nw-stream-slot]').length===count,{},count);const exported=await page.$eval('#batch-export',f=>Array.from(f.contentDocument.querySelectorAll('[data-nw-stream-slot] img'),n=>n.getAttribute('src')));assert.deepEqual(exported,changed.map(n=>n.src));await page.evaluate(()=>document.querySelector('#batch-export').remove());
  }
  // Hold real FileReader work to check locks, switching drafts and closing a session mid-batch.
  await page.evaluate(()=>{NAGWEB_MOTION_LAB.open();window.__batchNativeRead=FileReader.prototype.readAsDataURL;window.__batchPendingReaders=0;FileReader.prototype.readAsDataURL=function(file){const native=window.__batchNativeRead;window.__batchPendingReaders++;this.addEventListener('loadend',()=>window.__batchPendingReaders--,{once:true});setTimeout(()=>native.call(this,file),250);};});await page.click('[data-motion-template="iso-orbit"]');await ready(9);const idle=await slots();await upload(...files.slice(0,2));assert.equal(await page.$eval('[data-motion-stream-batch-open]',n=>n.disabled),true);assert.equal(await page.$eval('[data-motion-insert-group]',n=>n.disabled),true);assert.equal(await page.$eval('[data-motion-library-save]',n=>n.disabled),true);assert.equal(await page.$eval('[data-motion-upload-open]',n=>n.disabled),true);assert.equal(await page.$eval('[data-motion-image-preview]',n=>n.disabled),true);
  await page.click('[data-motion-template="showcase-stream"]');await ready(12);const other=await slots();await page.waitForFunction(()=>!document.querySelector('[data-motion-insert-group]').disabled);await page.click('[data-motion-template="iso-orbit"]');await page.waitForFunction(()=>!document.querySelector('[data-motion-stream-batch-open]').disabled);await ready(9);const cached=await slots();assert.equal(cached[0].width,300);assert.equal(cached[1].width,301);assert.deepEqual(cached.map(n=>n.id),idle.map(n=>n.id));await page.click('[data-motion-template="showcase-stream"]');await ready(12);assert.deepEqual(await slots(),other,'Finishing a cached batch does not modify the currently visible template');await page.click('[data-motion-close]');
  const closed=await page.evaluate(()=>JSON.stringify(project));await page.evaluate(()=>NAGWEB_MOTION_LAB.open());await page.click('[data-motion-template="iso-orbit"]');await ready(9);await upload(...files.slice(0,2));await page.click('[data-motion-close]');await page.evaluate(()=>NAGWEB_MOTION_LAB.open());await page.click('[data-motion-template="iso-orbit"]');await ready(9);await page.waitForFunction(()=>window.__batchPendingReaders===0&&!document.querySelector('[data-motion-stream-batch-open]').disabled);assert.ok((await slots()).every(n=>n.width===640),'A closed session cannot overwrite the new composition');assert.equal(await page.evaluate(()=>JSON.stringify(project)),closed);
  await fs.mkdir('/tmp/nagweb-motion-visuals',{recursive:true});await (await page.$('.nw-motion-dialog')).screenshot({path:'/tmp/nagweb-motion-visuals/batch-images.png'});await page.click('[data-motion-close]');
  console.log('Carga múltiple Motion Lab: archivos reales/orden vigente, reemplazo parcial y posiciones intactas, texto libre, lote inválido/excesivo sin cambios ni recursos parciales, bloqueo durante carga, borrador en segundo plano y cierre seguro, inserción/reapertura/guardado/historial/exportación en '+(templates?templates.join(', '):'Stream/Iso/Pop/Stage/Orbit Bloom/Ticker Tilt/Ticker Loop/Carousel Flow/Stack Slide/Iso Focus/Card Toss')+' OK');
 }finally{
  await page.evaluate(p=>{if(window.__batchNativeRead){FileReader.prototype.readAsDataURL=window.__batchNativeRead;delete window.__batchNativeRead;delete window.__batchPendingReaders;}document.querySelector('.nw-motion-dialog').close();document.querySelector('#batch-export')?.remove();clearTimeout(previewTimer);project=JSON.parse(p.project);curPage=p.curPage;curSec=p.curSec;curEl=p.curEl;curPane=p.curPane;selection=p.selection;secFocus=p.secFocus;history=[];future=[];NAGWEB_STORY_EDITOR.setCanvasMode(p.mode);NAGWEB_STORY_TIMELINE_UI.setState(p.timeline);saveProject();renderScenes();renderPane();renderPreview();},previous);await fs.rm(dir,{recursive:true,force:true});
 }
}
